import json
info=json.load(open('run_trace/phykit_metrics_tool.json'))
# Recursively summarize conditional names/selectors and total_tree_length branch paths
def walk(node, path=''):
    if isinstance(node, dict):
        if node.get('model_class')=='Conditional':
            print('COND', path, 'name=', node.get('name'), 'selector_name=', node.get('test_param',{}).get('name'), 'default=', node.get('test_param',{}).get('value'))
            for c in node.get('cases',[]):
                print('  CASE', c.get('value'), 'inputs:', [i.get('name') for i in c.get('inputs',[])])
        for k,v in node.items():
            walk(v, path+'/'+str(k))
    elif isinstance(node, list):
        for i,v in enumerate(node):
            walk(v, path+'/'+str(i))
walk(info.get('inputs', []))
PY"

