import csv, statistics, json
vals={}
with open('run_trace/galaxy_outputs/metrics.tsv', newline='') as f:
    for row in csv.DictReader(f, delimiter='\\t'):
        vals.setdefault(row['group'], []).append(float(row['value']))
med={g: statistics.median(v) for g,v in vals.items()}
ratio=med['fungi']/med['animals']
print(json.dumps({'counts':{g:len(v) for g,v in vals.items()}, 'medians':med, 'fungi_over_animals':ratio, 'animals_over_fungi':med['animals']/med['fungi']}, indent=2))
PY"

